-- Seed data for testing
-- 3 Networks, 5 Base Stations, 20 Talkgroups, 50 Radios



-- Generate 20 talkgroups

-- Generate 20 radios (will add more via mock)
DO $$
DECLARE i INTEGER;
BEGIN
    FOR i IN 1..20 LOOP
        VALUES (
            3000000 + i,
            LPAD(TO_HEX(3000000 + i), 6, '0'),
            'Unit-' || i,
            (i % 3 = 0)
        );
    END LOOP;
END $$;
